@if (!ShowForm)
{
    <button class="btn btn-outline-primary btn-sm w-100" @onclick="() => ShowForm = true">
        + Add Task
    </button>
}
else
{
    <div class="card">
        <div class="card-body p-2">
            <div class="mb-2">
                <input type="text" class="form-control form-control-sm" placeholder="Title" @bind="Title" />
            </div>
            <div class="mb-2">
                <input type="text" class="form-control form-control-sm" placeholder="Assignee" @bind="Assignee" />
            </div>
            <div class="mb-2">
                <select class="form-select form-select-sm" @bind="Priority">
                    <option value="">Select priority</option>
                    <option value="High">High</option>
                    <option value="Medium">Medium</option>
                    <option value="Low">Low</option>
                </select>
            </div>
            <div class="mb-2">
                <input type="date" class="form-control form-control-sm" @bind="DueDate" />
            </div>
            <div class="d-flex gap-1">
                <button class="btn btn-primary btn-sm" @onclick="Save" disabled="@IsSaving">
                    @(IsSaving ? "Saving..." : "Save")
                </button>
                <button class="btn btn-secondary btn-sm" @onclick="Cancel" disabled="@IsSaving">Cancel</button>
            </div>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public required string Status { get; set; }
    [Parameter, EditorRequired] public required EventCallback<TaskItem> OnTaskCreated { get; set; }
    [Parameter, EditorRequired] public required ITaskService TaskService { get; set; }

    private bool ShowForm;
    private bool IsSaving;
    private string Title = "";
    private string Assignee = "";
    private string Priority = "";
    private DateTime DueDate = DateTime.Today;

    private async Task Save()
    {
        if (string.IsNullOrWhiteSpace(Title) || string.IsNullOrWhiteSpace(Priority))
            return;

        IsSaving = true;
        try
        {
            var task = await TaskService.CreateTaskAsync(Title, Assignee, Priority, DueDate);
            await OnTaskCreated.InvokeAsync(task);
            ResetForm();
        }
        finally
        {
            IsSaving = false;
        }
    }

    private void Cancel() => ResetForm();

    private void ResetForm()
    {
        ShowForm = false;
        Title = "";
        Assignee = "";
        Priority = "";
        DueDate = DateTime.Today;
    }
}

@page "/board"
@using sv_45657d10a9a342648445502c0c99f4d5.Components.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="text-center py-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
        <p class="mt-2 text-muted">Loading tasks...</p>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-link" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar Tasks="tasks" />
    <TaskSearchBar SearchText="@searchText" SearchTextChanged="OnSearchTextChanged" />

    <div class="row g-3">
        <KanbanColumn Status="To Do"
                      Tasks="GetFilteredTasks(\"To Do\")"
                      CanMoveLeft="false"
                      CanMoveRight="true"
                      OnMoveLeft="_ => System.Threading.Tasks.Task.CompletedTask"
                      OnMoveRight="t => MoveTask(t, \"In Progress\")"
                      OnTaskCreated="OnTaskCreated"
                      TaskService="TaskService" />
        <KanbanColumn Status="In Progress"
                      Tasks="GetFilteredTasks(\"In Progress\")"
                      CanMoveLeft="true"
                      CanMoveRight="true"
                      OnMoveLeft="t => MoveTask(t, \"To Do\")"
                      OnMoveRight="t => MoveTask(t, \"Done\")"
                      OnTaskCreated="OnTaskCreated"
                      TaskService="TaskService" />
        <KanbanColumn Status="Done"
                      Tasks="GetFilteredTasks(\"Done\")"
                      CanMoveLeft="true"
                      CanMoveRight="false"
                      OnMoveLeft="t => MoveTask(t, \"In Progress\")"
                      OnMoveRight="_ => System.Threading.Tasks.Task.CompletedTask"
                      OnTaskCreated="OnTaskCreated"
                      TaskService="TaskService" />
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private IReadOnlyList<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private void OnSearchTextChanged(string value)
    {
        searchText = value;
    }

    private async Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = tasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                tasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private void OnTaskCreated(TaskItem task)
    {
        tasks.Add(task);
    }
}

